/* Force-included (after port/include/compat.h) into every file of END.EXE's C (SRC_END,
 * and port/end/lib) when they are compiled for the host.
 *
 * Like U.EXE's (port/u/uport.h): END's public names are renamed E_<name> (erename.h,
 * generated by port/tools/gen_u.py --prog end), and the OSI library's U_<name>, as END.EXE
 * links the same library, whose port (port/u/osilib) both use. END's main is E_main
 * (port/end/erun.c runs it). */
#ifndef E_EPORT_H
#define E_EPORT_H

#include "erename.h"
#undef main
#define main E_main

/* the graphics driver MCGADRV.BIN, in C: DRV(o)(...) is UDRV_o(...) (SRC_U/u.h) */
#include "ugfx.h"

#endif
